export type MarkdownHeading = {
  /** Heading level from 1 (largest) to 6 (smallest). */
  depth: number
  /** Plain-text heading content with all inline formatting stripped. */
  value: string
}

/** Matches an ATX heading: 1–6 leading hashes followed by a space, at the very start of a line. */
const ATX_HEADING = /^(#{1,6}) +(.*)$/

/** Matches the trailing closing hashes of an ATX heading (e.g. the `##` in `## Title ##`). */
const CLOSING_HASHES = /[ \t]+#+[ \t]*$/

/** Matches a setext `=` underline (depth 1), allowing up to three leading and any trailing spaces. */
const SETEXT_H1_UNDERLINE = /^ {0,3}=+[ \t]*$/

/** Matches a setext `-` underline (depth 2), allowing up to three leading and any trailing spaces. */
const SETEXT_H2_UNDERLINE = /^ {0,3}-+[ \t]*$/

/** Matches the opening or closing line of a fenced code block (``` or ~~~), up to three spaces indented. */
const FENCE = /^ {0,3}(`{3,}|~{3,})/

/**
 * Removes inline markdown formatting from a heading value, keeping the visible text.
 *
 * Handles bold, italic, strikethrough, inline code, links (keeping the text), images
 * (keeping the alt text) and raw HTML tags. Delimiters are only removed when they form a
 * matched pair, so a lone marker such as the `*` in `a*b` is preserved.
 */
const stripInlineFormatting = (value: string): string => {
  return (
    value
      // Images first so the leading `!` is consumed before the link rule runs.
      .replace(/!\[([^\]]*)\]\([^)]*\)/g, '$1')
      // Links: keep the link text, drop the target.
      .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
      // Inline code.
      .replace(/`([^`]+)`/g, '$1')
      // Bold before italic so `**text**` is not mistaken for two italic runs.
      .replace(/\*\*([^*]+)\*\*/g, '$1')
      .replace(/__([^_]+)__/g, '$1')
      // Strikethrough.
      .replace(/~~([^~]+)~~/g, '$1')
      // Italic.
      .replace(/\*([^*]+)\*/g, '$1')
      .replace(/_([^_]+)_/g, '$1')
      // Any remaining HTML tags.
      .replace(/<[^>]+>/g, '')
      .trim()
  )
}

/** Clamps a heading depth into the valid 1–6 range. */
const clampDepth = (depth: number): number => Math.min(6, Math.max(1, depth))

/**
 * Parses a markdown string and returns its headings.
 *
 * Recognizes both ATX headings (`# Title`) and setext headings (a line of text underlined with
 * `=` for depth 1 or `-` for depth 2). Content inside fenced (``` / ~~~) and indented (4 spaces)
 * code blocks is ignored, and all inline formatting is stripped from the returned value.
 *
 * @param markdown - The markdown string to parse.
 * @returns An array of `{ depth, value }` heading objects, or an empty array when none are found.
 *
 * @example
 * getMarkdownHeadings('# Getting Started\n\nIntro\n\nInstallation\n------------')
 * // Returns:
 * // [
 * //   { depth: 1, value: 'Getting Started' },
 * //   { depth: 2, value: 'Installation' },
 * // ]
 */
export const getMarkdownHeadings = (markdown: string): MarkdownHeading[] => {
  if (!markdown) {
    return []
  }

  // Normalize Windows (CRLF) and old-Mac (CR) line endings.
  const lines = markdown.replace(/\r\n/g, '\n').replace(/\r/g, '\n').split('\n')

  const headings: MarkdownHeading[] = []

  // Tracks the delimiter of an open fenced code block, or null when not inside one.
  let fenceMarker: string | null = null

  for (let index = 0; index < lines.length; index++) {
    const line = lines[index]

    // Toggle fenced code blocks on and off, and skip everything inside them.
    const fence = line.match(FENCE)
    if (fence) {
      const marker = fence[1][0]
      if (fenceMarker === null) {
        fenceMarker = marker
      } else if (marker === fenceMarker) {
        fenceMarker = null
      }
      continue
    }
    if (fenceMarker !== null) {
      continue
    }

    // Indented code blocks (4-space indent) are never headings.
    if (/^ {4,}/.test(line)) {
      continue
    }

    // ATX heading (e.g. `## Title ##`).
    const atx = line.match(ATX_HEADING)
    if (atx) {
      const value = stripInlineFormatting(atx[2].replace(CLOSING_HASHES, ''))

      if (value) {
        headings.push({ depth: clampDepth(atx[1].length), value })
      }
      continue
    }

    // Setext heading: a non-empty line of text underlined with `=` (depth 1) or `-` (depth 2).
    const nextLine = lines[index + 1]
    if (nextLine !== undefined && line.trim() !== '') {
      const isSetextH1 = SETEXT_H1_UNDERLINE.test(nextLine)
      const isSetextH2 = SETEXT_H2_UNDERLINE.test(nextLine)

      if (isSetextH1 || isSetextH2) {
        const value = stripInlineFormatting(line.trim())

        if (value) {
          headings.push({ depth: isSetextH1 ? 1 : 2, value })
          // Skip the underline so it is not reprocessed.
          index += 1
          continue
        }
      }
    }
  }

  return headings
}
