      depth: 1,
      value: DEFAULT_DESCRIPTION_ENTRY.TITLE,
      slug: DEFAULT_DESCRIPTION_ENTRY.SLUG,
    }

    const id = generateId({
      type: 'text',
      depth: heading.depth,
      slug: heading.slug,
      parentId: parentId,
      info,
      value: heading.value,
    })

    const entry = {
      id,
      title: heading.value,
      type: 'text',
    } satisfies TraversedDescription

    // Push to entries
    entries.push(entry)

    descriptionHeadingsEntry = entry
  }

  // Go through each heading
  for (const heading of headings) {
    // Skip if not a main or sub heading
    if (heading.depth !== lowestLevel && heading.depth !== lowestLevel + 1) {
      continue
    }

    const entry: TraversedDescription = {
      id: generateId({
        type: 'text',
        depth: heading.depth,
        slug: heading.slug,
        parentId: parentId,
        info: info,
        value: heading.value,
      }),
      title: heading.value,
      type: 'text',
    }

